      _clAllCards().catch(function () { return []; }),
      // Team guidance, not just the playbook. The audit scores the draft
      // against ELI's stated positions, and without this it was scoring
      // against the playbook alone.
      _loadGuidance((_egActive.interview && _egActive.interview.agreementType) || "", { text: _ivText(_egActive.interview) })
        .catch(function () { return []; }),
