  // Structure completeness, run in rounds. Nothing is drafted yet, so a
  // missing clause costs one line in a list rather than a re-draft.
  function _runStructureAudit() {
    if (!_egActive) return Promise.resolve();
    _egActive.structureRounds = [];
    _egActive.structureAdded = [];
    _egActive.status = "structure_audit";
    _renderOverlayBody();

    function round(n) {
      if (!_egActive || n > STRUCTURE_AUDIT_MAX) return Promise.resolve();
      _egActive.structureRound = n;
      _stream("stage", "Completeness check, round " + n,
        "against " + (_egActive.outline || []).length + " parts");
      _renderOverlayBody();
      return _aiJsonCall(
        _buildStructureAuditPrompt(_egActive, n, _egActive.structureAdded),
        { missing: "object" }
      ).then(function (r) {
        if (!_egActive) return;
        var missing = ((r && r.missing) || []).filter(function (m) {
          // A clause already in the list is not missing, whatever the
          // model says — proposing a near-duplicate is worse than a miss.
          return m && m.name && !_stHas(_egActive.outline, m.name);
        });
        _egActive.structureRounds.push({
          round: n, found: missing.length,
          complete: missing.length === 0,
        });
