      // and takes the WHOLE insert down with it.
      var fm = _egActive && _egActive.frontMatter;
      // Every shape comes from the document type — front matter, how the
      // body runs, and what closes it.
      var dtName = (_egActive.interview && _egActive.interview.agreementType) || "";
      var lines = _fmLayout(fm, dtName)
        .concat(_diLayout(accepted, dtName))
        .concat(_fmSignatureLayout(fm, dtName));
