  // Word's own multi-level numbering, so inserting or deleting a clause
  // renumbers everything after it. Level 0 "1.", level 1 "1.1", level 2
  // "(a)" — and front matter and the execution block stay out of it.
  //
  // The list APIs are the most host-dependent surface this tool touches, so
  // when any part of this refuses, the literal labels _diLayout already
  // computed are written into the text instead. A statically numbered
  // contract is a far better outcome than an unnumbered one.
  function _diApplyNumbering(context, made) {
    var listed = made.filter(function (m) { return m.listLevel >= 0; });
    if (!listed.length) return context.sync();
    var theList = null;
    try {
      theList = listed[0].p.startNewList();
      theList.load("id");
    } catch (_e) { theList = null; }
    return context.sync().then(function () {
      if (theList) {
        try {
          theList.setLevelNumbering(0, Word.ListNumbering.arabic, [0, "."]);
          theList.setLevelNumbering(1, Word.ListNumbering.arabic, [0, ".", 1]);
          theList.setLevelNumbering(2, Word.ListNumbering.lowerLetter, ["(", 2, ")"]);
          for (var i = 1; i < listed.length; i++) {
            listed[i].p.attachToList(theList.id, listed[i].listLevel);
          }
          return context.sync().then(function () { return true; });
        } catch (_e2) { /* fall through to literal numbering */ }
      }
      return _diLiteralNumbering(context, listed);
    }).catch(function () {
      return _diLiteralNumbering(context, listed);
    });
  }

  function _diLiteralNumbering(context, listed) {
    listed.forEach(function (m) {
      // Out of any list first, or Word adds its own number alongside ours.
      try { m.p.detachFromList(); } catch (_e) {}
      if (m.label) {
        try { m.p.insertText(m.label + "  ", "Start"); } catch (_e2) {}
      }
    });
    return context.sync().then(function () { return false; });
  }

  // House format. Times New Roman 11 on everything ELI writes, so an
  // inserted draft matches the documents around it; the title, the recitals
  // header and every section heading centred; clause titles bold.
  function _diApplyStyles(context, made) {
    made.forEach(function (m) {
      try { m.p.font.name = "Times New Roman"; m.p.font.size = 11; } catch (_e) {}
      // Paragraphs Word is numbering get their indent from the list, and
      // setting leftIndent on top of that double-indents them.
