          try { m.p.style = "Title"; } catch (_e4) {}
        }
        // Then the house format on top, or the style's own font wins.
        try {
          m.p.font.name = "Times New Roman";
          m.p.font.size = 14;
          m.p.font.bold = true;
          m.p.font.color = "#000000";
        } catch (_e5) {}
        try { m.p.alignment = "Centered"; } catch (_e6) {}
        try { m.p.spaceAfter = 18; } catch (_e7) {}
