        try {
          m.p.font.name = "Times New Roman";
          m.p.font.size = 11;
          m.p.font.bold = true;
          m.p.font.color = "#000000";
        } catch (_e8) {}
        try { m.p.alignment = "Centered"; } catch (_e9) {}
        try { m.p.spaceBefore = 12; m.p.spaceAfter = 6; } catch (_e10) {}
        return;
      }
      // A memo's or policy's section heading. Same Word style as a
      // contract heading so navigation and the clause indexer still see it,
      // but ranged left — a centred heading inside a memo reads as a title
      // for the whole document rather than a heading for what follows.
      if (m.kind === "subhead") {
