  function _buildSectionDraftPrompt(active, section) {
    var iv = active.interview || {};
    // Retrieval already decided where this section's language comes from —
    // the old substring match over every playbook entry is gone. Reaching
    // here means the tier is "adapt" or "generate"; anything stronger was
    // used verbatim and never came to the model.
    var r = (active.retrieval || {})[section.id] || {};
    var pbBlock = "";
    if (r.tier === "adapt" && r.text) {
      pbBlock = "\n═══ THE CLOSEST LANGUAGE WE HAVE ═══\n" +
        String(r.text).replace(/\n/g, " ").slice(0, 1200) +
        "\nSource: " + (r.provenance || "our library") + "\n" + (r.why || "") +
        "\nADAPT this to the present agreement. Keep its structure and defined" +
        " terms where they still work; change what does not fit. Do not copy" +
        " any party name, figure or date from it.";
