    var token = (eli.cancel && typeof eli.cancel.token === "function")
      ? eli.cancel.token() : null;
    if (_egActive) _egActive.cancelToken = token;
    var opts = { sanitize: false, tool: "eli_agent" };   // [AI-WHOSE] as _aiJsonCall
    if (extra) {
      if (extra.maxTokens) opts.maxTokens = extra.maxTokens;
      if (typeof extra.temperature === "number") opts.temperature = extra.temperature;
      if (typeof extra.thinkingBudget === "number") opts.thinkingBudget = extra.thinkingBudget;   // [TD-THINK]
      if (extra.inlineData) opts.inlineData = extra.inlineData;
    }
    if (token && token.signal) opts.signal = token.signal;
    var send = function () { return eli.ai.complete(ELI_WHO + prompt, opts); };
    var go = _db.replay && !opts.inlineData ? function () { return _dbAi("text", [opts.maxTokens, opts.temperature], prompt, send); } : send;   // [DEBUG-BRIDGE] replay
