      var lines = para.split("\n");
      // A heading on its own line.
      var h = lines.length === 1 && lines[0].match(/^(#{1,4})\s+(.+)$/);
      if (h) return '<div class="_eg_md_h">' + _mdInline(h[2]) + "</div>";
      // A block quote — how the model presents quoted clause language,
      // which is most of what a research answer contains.
      if (lines.every(function (l) { return /^\s*>\s?/.test(l); })) {
        return '<blockquote class="_eg_md_q">' +
          lines.map(function (l) { return _mdInline(l.replace(/^\s*>\s?/, "")); }).join("<br>") +
          "</blockquote>";
      }
      if (lines.every(function (l) { return /^\s*[-*•]\s+/.test(l); })) {
        return "<ul>" + lines.map(function (l) {
          return "<li>" + _mdInline(l.replace(/^\s*[-*•]\s+/, "")) + "</li>";
        }).join("") + "</ul>";
      }
      if (lines.every(function (l) { return /^\s*\d+[.)]\s+/.test(l); })) {
