  // ─── [/RESEARCH] ──────────────────────────────────────────────────

  // ─── [DRAFT-PREVIEW] ──────────────────────────────────────────────
  // The whole document, as it will be inserted, before it is inserted.
  //
  // The sections review shows each part in its own card, which answers
  // "is this clause right" and never "is this a document". Between
  // telling it to draft and clicking insert there was nowhere to read the
  // thing itself — so the run ended with the reader agreeing to something
  // they had not seen whole.
  //
  // Built from the SAME three layout functions the insert uses, so this
  // is what goes into the document rather than an impression of it. If
  // the numbering is wrong here it will be wrong there, which is the
  // point of looking.
  // TO REMOVE: delete to [/DRAFT-PREVIEW] + the two buttons that open it.

  function _dpRows() {
    if (!_egActive) return [];
    var accepted = (_egActive.outline || []).filter(function (s) {
      return (_egActive.draftAcceptance[s.id] || "accept") === "accept" && s.content;
