    var dt = _dtName();
    return _fmLayout(_egActive.frontMatter, dt)
      .concat(_diLayout(accepted, dt))
      .concat(_fmSignatureLayout(_egActive.frontMatter, dt));
  }

  // Escaped FIRST, then the placeholders are marked — _esc leaves square
  // brackets alone, so the marker cannot be forged by the drafted text.
  function _dpText(s) {
    return _esc(s).replace(/\[\[([^\]]{1,80})\]\]/g,
      '<mark class="_eg_dp_ph">[[$1]]</mark>');
  }

  function _dpRowHtml(r) {
    var style = r.indent ? ' style="margin-left:' + (r.indent * 18) + 'px"' : "";
    // The number lives in `label`, exactly as at insert time, where Word's
    // own list numbering writes it. Shown here so the reader sees the
    // hierarchy rather than a wall of paragraphs.
    var label = r.label
      ? '<span class="_eg_dp_num">' + _esc(r.label) + '</span>' : "";
    return '<p class="_eg_dp_p _eg_dp_' + _esc(r.kind || "clause") + '"' + style + '>' +
      label + _dpText(r.text) + '</p>';
  }

  function _dpBodyHtml() {
    var rows = _dpRows();
    if (!rows.length) {
      return '<div class="_eg_dp_empty">Nothing to insert — every section is ' +
        'either skipped or empty.</div>';
    }
    var words = 0, ph = 0;
    rows.forEach(function (r) {
      words += String(r.text || "").split(/\s+/).filter(Boolean).length;
      ph += _dcPlaceholders(r.text).length;
    });
