    cms.load("items/id");
    return context.sync().then(function () { return (cms.items || []).filter(function (c) { return c.id === wordId; })[0] || null; });
  }
  function _scLocate(f) {
    eli.host.runRaw("eli_agent:sc_locate", function (context) {
      var go = f.locate.kind === "comment"
        ? _scComment(context, f.locate.wordId).then(function (c) { return c ? c.getRange() : null; })
        : _scRangeFor(context, f.locate);
      return go.then(function (r) {
        if (!r) throw new Error("gone");
        r.select();
        return context.sync();
      });
    }).catch(function () { if (typeof showToast === "function") showToast("Couldn't find that in the document any more.", "info"); });
  }
  // One fix. Each leaves the document's track-changes setting as it is.
  function _scFix(f) {
    var x = f.fix;
    if (x.kind === "turn_draft") {
      _openAgentOverlay({ agent: "turn_draft", instruction: "" });
      return Promise.resolve();
    }
    if (x.kind === "bookmarks") {
      return eli.host.cleanupAnchors(["ELI_", "EGA_", "EliReviseAnchor"]).then(function () {
        if (typeof eli.host.invalidateCache === "function") eli.host.invalidateCache();
        f.state = "fixed";
      }, function () { f.error = "Word couldn't remove them."; });
    }
    return eli.host.runRaw("eli_agent:sc_fix", function (context) {
      var doc = context.document;
      if (x.kind === "tracking_on") { doc.changeTrackingMode = "TrackAll"; return context.sync(); }
      if (x.kind === "clear_props") {
        x.fields.forEach(function (k) { doc.properties[k] = ""; });
        return context.sync();
      }
      if (x.kind === "remove_comment") {
        return _scComment(context, x.wordId).then(function (c) { if (!c) throw new Error("That comment is already gone."); c.delete(); return context.sync(); });
      }
      if (x.kind === "remove_reply") {
        return _scComment(context, x.wordId).then(function (c) {
          // Its comment already removed (an earlier fix): the reply went with it.
          if (!c) return null;
          c.replies.load("items/id");
          return context.sync().then(function () {
            var r = (c.replies.items || []).filter(function (y) { return y.id === x.replyId; })[0];
            if (!r) throw new Error("That reply is already gone.");
            r.delete();
            return context.sync();
          });
        });
      }
      if (x.kind === "remove_resolved") {
        var cms = doc.body.getComments();
        cms.load("items/id");
        return context.sync().then(function () {
          (cms.items || []).forEach(function (c) { if (x.ids.indexOf(c.id) >= 0) c.delete(); });
          return context.sync();
        });
      }
      if (x.kind === "unhighlight") {
        var hs = doc.body.search(String(x.text).slice(0, 240), { matchCase: true });
        hs.load("items");
        return context.sync().then(function () {
          if (hs.items.length) return hs.items;
          return Promise.resolve(eli.host.helpers.searchWithFallback(doc.body.getRange("Whole"), String(x.text).slice(0, 240), context)).then(function (h) { return h ? [h] : []; });
        }).then(function (items) {
          if (!items.length) throw new Error("Couldn't find the highlighted words.");
          items.forEach(function (h) { h.font.highlightColor = null; });
          return context.sync();
        });
      }
      if (x.kind === "match_font") {
        var ps = doc.body.paragraphs;
        ps.load("items");
        return context.sync().then(function () {
          x.paras.forEach(function (i) { var p = ps.items[i]; if (p) p.font[x.prop === "size" ? "size" : "name"] = x.value; });
          return context.sync();
        });
      }
      if (x.kind === "replace") {
        return _scRangeFor(context, { kind: "para", i: x.i, text: x.find }).then(function (r) {
          if (!r) throw new Error("Couldn't find those words any more.");
          r.load("text");
          return context.sync().then(function () {
            if (_egNorm(r.text).toLowerCase() !== _egNorm(x.find).toLowerCase()) throw new Error("Those words have changed; nothing was replaced.");
            // Only the words that differ, against the document's own text, so
            // the redline (if tracking is on) is small and unchanged words keep
            // their characters.
            var hunks = _egTokenDiff(String(r.text), String(x.to));
            var merged = hunks.map(function (hk) { return hk.type === "equal" ? hk.old : hk["new"]; }).join("");
            var changed = hunks.filter(function (hk) { return hk.type === "change"; });
            var one = changed.length === 1 && changed[0].old.trim() && String(r.text).split(changed[0].old).length === 2 ? changed[0] : null;
            if (one) {
              var h = r.search(one.old, { matchCase: true });
              h.load("items");
              return context.sync().then(function () {
                if (h.items.length !== 1) { r.insertText(merged, "Replace"); return context.sync(); }
                if (one["new"].trim()) h.items[0].insertText(one["new"], "Replace"); else h.items[0].delete();
                return context.sync();
              });
            }
            r.insertText(merged, "Replace");
            return context.sync();
          });
        });
      }
      return Promise.resolve();
    }).then(function () { if (f.state === "open") { f.state = "fixed"; f.error = ""; } }, function (e) { f.error = _egErr(e, "Word couldn't make this fix."); });
  }
  // ─── [/SEND-CHECK] ────────────────────────────────────────────────

  // ─── Manage Agents modal ──────────────────────────────────────────
  // Barebones V1: list every registered agent with an enable toggle
  // and the agent's description. Tone/scope controls render but only
  // tone is editable in V1 (scope checkboxes ship in Phase 2 once the
  // planning prompt actually consumes them).
  function _openManageAgentsModal() {
    _closeManageAgentsModal();
    var modal = document.createElement("div");
    modal.id = "_eg_manage_modal";
    modal.className = "_eg_modal_backdrop";
    modal.innerHTML =
      '<div class="_eg_modal_panel">' +
        '<div class="_eg_modal_header">' +
          '<div class="_eg_modal_title">⚙ Manage Agents</div>' +
          '<button id="_eg_manage_close" type="button" class="_eg_btn_ghost">✕</button>' +
        '</div>' +
        '<div id="_eg_manage_body" class="_eg_modal_body">' +
          '<div style="font-size:11px;color:#64748b;text-align:center;padding:24px;">Loading agents…</div>' +
        '</div>' +
      '</div>';
    document.body.appendChild(modal);
    document.getElementById("_eg_manage_close").onclick = _closeManageAgentsModal;
    modal.onclick = function (ev) { if (ev.target === modal) _closeManageAgentsModal(); };
    _renderManageAgentsBody();
  }
  function _renderManageAgentsBody() {
    var body = document.getElementById("_eg_manage_body");
    if (!body) return;
    Promise.all(AGENT_REGISTRY.map(function (a) {
      return _getAgentSettings(a.id).then(function (s) { return { agent: a, settings: s }; });
    })).then(function (rows) {
      var html = '';
      rows.forEach(function (row) {
        var enabled = row.settings.enabled !== false;
        var tone = row.settings.tone || "balanced";
        html +=
          '<div class="_eg_manage_card">' +
            '<div class="_eg_manage_card_head">' +
              '<div class="_eg_manage_card_title">' +
                '<span style="font-size:18px;">' + _esc(row.agent.icon) + '</span>' +
                '<span>' + _esc(row.agent.displayName) + '</span>' +
              '</div>' +
              '<label class="_eg_toggle">' +
                '<input type="checkbox" data-eg-toggle-agent="' + _esc(row.agent.id) + '"' + (enabled ? ' checked' : '') + '>' +
                '<span>' + (enabled ? 'Enabled' : 'Disabled') + '</span>' +
              '</label>' +
            '</div>' +
            '<div class="_eg_manage_card_desc">' + _esc(row.agent.description) + '</div>' +
            '<div class="_eg_manage_card_settings">' +
              '<label class="_eg_setting_label">Default tone</label>' +
              '<select data-eg-tone="' + _esc(row.agent.id) + '">' +
                '<option value="conservative"' + (tone === "conservative" ? ' selected' : '') + '>Conservative</option>' +
                '<option value="balanced"' + (tone === "balanced" ? ' selected' : '') + '>Balanced</option>' +
                '<option value="aggressive"' + (tone === "aggressive" ? ' selected' : '') + '>Aggressive</option>' +
              '</select>' +
            '</div>' +
          '</div>';
      });
      body.innerHTML = html + '<div id="_eg_cl_panel" class="_eg_manage_card"></div>';
      _wireManageAgentsControls();
      _renderClausePanel();
    }).catch(function (err) {
      body.innerHTML = '<div style="font-size:11px;color:#991b1b;padding:24px;text-align:center;">Failed to load agents: ' + _esc(err && err.message) + '</div>';
    });
  }
  // The shape the parser saw, shown when a template yields nothing. Without
  // it "no clauses found" is a dead end — this says whether the OOXML even
  // parsed, and what the headings actually look like.
  function _clDiagHtml(d) {
    if (!d) return "";
    var shape = d.looksPackage ? "flat-OPC package" : (d.looksDocument ? "w:document" : "unrecognised");
    var rows =
      '<div class="_eg_cl_diag">' +
        '<div>' + _esc(shape) + ', ' + d.bytes.toLocaleString() + ' chars — ' +
          d.paras + ' paragraphs (' + d.nonEmpty + ' with text, ' + d.inTable + ' in tables)</div>' +
        '<div>raw &lt;w:p&gt; in the text: ' + (d.rawParas || 0) +
          ' · w:body present: ' + (d.rawBody ? "yes" : "no") +
          ' · pkg:part elements: ' + (d.parts === undefined ? "?" : d.parts) +
          ' · root: ' + _esc(String(d.rootName || "?")) + '</div>' +
        (d.parseError
          ? '<div><b>XML parse error:</b> ' + _esc(d.parseError) + '</div>'
          : '<div>XML parsed without error</div>') +
        (d.prolog ? '<div>starts: ' + _esc(d.prolog) + '</div>' : "") +
        '<div>' + d.headings + ' detected as headings · ' + d.withOutline +
          ' with outline level · ' + d.withNumbering + ' auto-numbered</div>';
    if (d.styles && d.styles.length) {
      rows += '<div>styles: ' + d.styles.map(function (s) {
        return _esc(s.style) + '×' + s.n;
      }).join(", ") + '</div>';
    }
    if (d.samples && d.samples.length) {
      rows += '<div class="_eg_cl_diag_samples">' + d.samples.map(function (s) {
        return '<div><span class="_eg_cl_dim">[' + _esc(s.style) +
          (s.outline >= 0 ? ' o' + s.outline : '') + (s.numbered ? ' num' : '') +
          ' lvl' + s.level + ']</span> ' + _esc(s.text) + '</div>';
      }).join("") + '</div>';
    }
    return rows + '</div>';
  }

  // Clause library panel — builds the index the drafting agent retrieves
  // from, so a draft reuses vetted language instead of generating prose.
  function _renderClausePanel(report) {
    var el = document.getElementById("_eg_cl_panel");
    if (!el) return;
    _clReadManifest().then(function (man) {
      var tpls = (man && man.templates) || [];
      var status;
      if (report && report.missing && report.missing.length) {
        status = '<div class="_eg_cl_warn">' +
          report.missing.map(function (m) {
            return '<div>' + _esc(m.label) + ' — not indexed: ' + _esc(m.reason) + '</div>' +
              _clDiagHtml(m.diag);
          }).join("") + '</div>';
      } else { status = ""; }
      var listed = tpls.length
        ? '<ul class="_eg_cl_list">' + tpls.map(function (x) {
            return '<li><b>' + _esc(x.templateName) + '</b> — ' +
              x.cardCount + ' clause' + (x.cardCount === 1 ? '' : 's') +
              (x.agreementType ? ' <span class="_eg_cl_dim">(' + _esc(x.agreementType) + ')</span>' : '') +
            '</li>';
          }).join("") + '</ul>' +
          '<div class="_eg_cl_dim">Built ' + _esc(String(man.builtAt || "").slice(0, 10)) + '</div>'
        : '<div class="_eg_cl_dim">No clause index yet. The drafting agent will generate every ' +
          'section from scratch until one is built.</div>';
      el.innerHTML =
        '<div class="_eg_manage_card_head">' +
          '<div class="_eg_manage_card_title"><span style="font-size:18px;">📚</span>' +
            '<span>Clause library</span></div>' +
          '<button id="_eg_cl_build" type="button" class="_eg_btn_secondary">' +
            (tpls.length ? 'Rebuild' : 'Build index') + '</button>' +
        '</div>' +
        '<div class="_eg_manage_card_desc">Indexes the services agreement, the NDA and the research agreement into ' +
          'reusable clauses, so drafts start from your own language.</div>' +
        status + listed;
      var btn = document.getElementById("_eg_cl_build");
      if (btn) btn.onclick = function () {
        btn.disabled = true; btn.textContent = "Indexing…";
        _clBuildIndex().then(function (r) {
          _renderClausePanel(r);
        }).catch(function (e) {
          el.innerHTML = '<div class="_eg_cl_warn">Indexing failed: ' + _esc(e && e.message) + '</div>';
        });
      };
    });
  }
  function _wireManageAgentsControls() {
    document.querySelectorAll("[data-eg-toggle-agent]").forEach(function (cb) {
      cb.onchange = function () {
        var id = cb.getAttribute("data-eg-toggle-agent");
        _getAgentSettings(id).then(function (s) {
          s.enabled = cb.checked;
          return _setAgentSettings(id, s);
        }).then(function () {
          _renderManageAgentsBody();  // refresh enabled-state label
        });
      };
    });
    document.querySelectorAll("[data-eg-tone]").forEach(function (sel) {
      sel.onchange = function () {
        var id = sel.getAttribute("data-eg-tone");
        _getAgentSettings(id).then(function (s) {
          s.tone = sel.value;
          return _setAgentSettings(id, s);
        });
      };
    });
  }
  function _closeManageAgentsModal() {
    var modal = document.getElementById("_eg_manage_modal");
    if (modal && modal.parentNode) modal.parentNode.removeChild(modal);
  }

  // ─── Bus listener: paint dropdown when ask_eli mounts its input ───
  // ask_eli emits 'ask_eli:input_mounted' (additive patch) with
  // { slotEl, sendBtn, inputEl, getQaContext }. We paint into slotEl
  // and mark the send button for label-flip. If ask_eli isn't
  // patched yet (older bundle), this listener simply never fires.
  // Bundle CSS is auto-injected by the kernel from style.css — no
  // manual injection needed.
  if (eli.bus && typeof eli.bus.on === "function") {
    eli.bus.on("ask_eli:input_mounted", function (payload) {
      _loadAutoRoute();
      _paintDropdown(payload);
    });
  }

  // ─── Dispatch handlers ────────────────────────────────────────────
  // intercept_submit: ask_eli calls this BEFORE running its Q&A
  // pipeline. If the current mode isn't "ask_eli", we open the agent
  // overlay and return { handled: true } to short-circuit ask_eli's
  // Q&A path. Returning falsy lets Q&A proceed normally.
  // [ASK-SETTINGS] Rows for Ask ELI's settings dialog. Ask ELI draws them;
  // this tool keeps owning the state (Auto in eli_agent_auto_route, the mode
  // in _currentMode).
  function _settingsRows() {
    _loadAutoRoute();
    return _listAgents().then(function (agents) {
      var modes = [{ value: "ask_eli", label: "Ask ELI" }].concat(
        agents.filter(function (a) { return a.enabled; }).map(function (a) {
          return { value: "agent:" + a.id, label: a.displayName };
        }));
      return [
        { type: "switch", key: "eli_agent_auto", label: "Auto",
          help: "Let ELI decide whether to answer or revise the document.",
          value: _autoRoute, set: function (v) { _setAutoRoute(!!v); } },
        { type: "select", key: "eli_agent_mode", label: "Mode",
          help: "Leave on Ask ELI and Auto decides; pick an agent to send every question to it.",
          value: _currentMode, options: modes, set: function (v) { _setMode(String(v)); } },
        { type: "action", key: "eli_agent_manage", label: "Manage agents…",
          run: function () { _openManageAgentsModal(); } },
      ];
    });
  }

  // [AGENT-SETTINGS] The Agents tab of Ask ELI's settings: each agent's own
  // options. Ask ELI draws it; the settings stay in this tool's agent rows.
  function _settingsTab() {
    return _getAgentSettings("turn_draft").then(function (s) {
      return [{ title: "Respond to Redlines", rows: [
        { type: "switch", key: "td_strike_rejected", label: "Strike through rejected additions",
          help: "Off: an addition of theirs you reject is removed (Word's Reject). On: it stays, struck through as your deletion, so they see what Colgate took out.",
          value: !!(s && s.strikeRejected),
          set: function (v) {
            return _getAgentSettings("turn_draft").then(function (cur) { return _setAgentSettings("turn_draft", Object.assign({}, cur, { strikeRejected: !!v })); });
          } },
        { type: "switch", key: "td_outside_body", label: "Include headers, footers and footnotes",
          help: "Off: only the body is read; ELI says how many of their changes sit in headers, footers or footnotes. On: those are answered too (a moment longer to read and apply). Word takes no comments in headers or footers, so notes there go in the issues list and cover email.",
          value: !!(s && s.outsideBody),
          set: function (v) {
            return _getAgentSettings("turn_draft").then(function (cur) { return _setAgentSettings("turn_draft", Object.assign({}, cur, { outsideBody: !!v })); });
          } },
        { type: "switch", key: "td_follow_word", label: "Follow your place in Word",
          help: "On: while you review ELI's answers, clicking into a clause in Word brings its card into view (and its row in the Issues list). Off: the review stays where you leave it.",
          value: !(s && s.followWord === false),
          set: function (v) {
            return _getAgentSettings("turn_draft").then(function (cur) { return _setAgentSettings("turn_draft", Object.assign({}, cur, { followWord: !!v })); });
          } },
      ].concat(_tdIsOwner() ? [   // [PRECEDENT] the owner's preview
        { type: "switch", key: "td_precedent_preview", label: "Precedent preview (sample data)",
          help: "Only you see this. Shows, on Respond's cards, what colleagues did before with the same kind of change — made-up sample patterns, for shaping the screens. Counts and anonymous facts only. It never changes a decision.",
          value: !!(s && s.precedentPreview),
          set: function (v) {
            return _getAgentSettings("turn_draft").then(function (cur) { return _setAgentSettings("turn_draft", Object.assign({}, cur, { precedentPreview: !!v })); });
          } },
      ] : []) }];
    });
  }

  eli.register({
    eli_agent: {
      list_agents: function () { return _listAgents(); },
      settings_tab: function () { return _settingsTab(); },
      settings_rows: function () { return _settingsRows(); },
      // [POSITIONS] Team guidance + playbook clauses for an agreement type —
      // the same loaders the playbook pass and research use, for Ask ELI.
      positions_for: function (docType) {
        return Promise.all([_loadGuidance(docType || ""), _loadPlaybookSnippets(docType || "")])
          .then(function (r) { return { guidance: r[0] || [], playbooks: r[1] || [] }; });
      },
      get_agent_settings: function (agentId) { return _getAgentSettings(agentId); },
      set_agent_settings: function (payload) {
        if (!payload || !payload.agentId) return Promise.reject(new Error("Missing agentId"));
        return _setAgentSettings(payload.agentId, payload.settings || {});
      },
      intercept_submit: function (payload) {
        var text = (payload && payload.instruction) || "";
        // [TD-REPORT] "!…" is a command, not a request: the owner's !td-report here, the rest (!debug…) Ask ELI's own.
        if (/^\s*!td-report\s*$/i.test(text) && _tdIsOwner()) { _tdReportCopy(); return { handled: true }; }
        if (/^\s*!/.test(text)) return { handled: false };
        // [RESPOND-TYPED] "respond to the redlines [in section 4]" — in any mode, decided here (no AI): a section named
        // scopes it (at the decide); none named, the selection if any, else the whole document.
        var head = _routeHead(text);
        if (head && !_answerAsIs && RE_TURN.test(head)) {
          var sel = String((payload && payload.selectionText) || "").trim();
          _lastRouteWhy = "";   // the note's own words say it ("Read as a request to answer their markup")
          _openAgentOverlay({ agent: "turn_draft", instruction: text, selectionOnly: !_tdScopeRefs(text).length && sel.length >= 4,
            qaIndex: payload && payload.qaIndex, docHash: payload && payload.docHash, routedAuto: true, routedTo: "TURN", routedText: text });
          return { handled: true };
        }
        // An explicitly chosen mode always wins — the dropdown is the
        // user saying what they want, and nothing should second-guess it.
        if (_currentMode && _currentMode !== "ask_eli") {
          _openAgentOverlay({
            agent: _currentMode.replace(/^agent:/, ""),
            instruction: text,
            qaIndex: payload && payload.qaIndex,
            docHash: payload && payload.docHash,
          });
          return { handled: true };
        }
        // Auto off — Ask ELI is untouched, synchronously, exactly as before.
        if (!_autoRoute) return { handled: false };
        // Auto on — read it first. Returns a promise; ask_eli awaits it.
        return _routeInstruction(text).then(function (route) {
          // Comments: back to Ask ELI, told it is a comment request.
          if (route === "COMMENT") return { handled: false, route: "COMMENT" };
          if (route === "CHOOSE") {
            _openAgentOverlay({ agent: _lastRouteGuess === "DRAFT" ? "draft_agreement" : "apply_instruction", instruction: text,
              qaIndex: payload && payload.qaIndex, docHash: payload && payload.docHash, routedAuto: true, routedTo: _lastRouteGuess, routedText: text, choose: true });
            return { handled: true };
          }
          if (route === "TURN" || route === "SEND") {   // [TURN-DRAFT] [SEND-CHECK]
            _openAgentOverlay({ agent: route === "TURN" ? "turn_draft" : "send_check", instruction: route === "TURN" ? text : "",
              routedAuto: true, routedTo: route, routedText: text });
            return { handled: true };
          }
          if (route !== "REVISE" && route !== "DRAFT") return { handled: false };
          _openAgentOverlay({
            // DRAFT writes something new; REVISE changes what is open. The
            // instruction becomes the drafter's intake seed either way.
            agent: route === "DRAFT" ? "draft_agreement" : "apply_instruction",
            instruction: text,
            qaIndex: payload && payload.qaIndex,
            docHash: payload && payload.docHash,
            routedAuto: true,
            routedTo: route,
          });
          return { handled: true };
        });
      },
      // Returns whether it opened, so a caller can tell "eli_agent is not
      // installed" (dispatch gives undefined) from "it opened" — an
      // unknown agent id returns ok:false rather than failing silently.
      // [TURN-DRAFT] Does the highlighted text hold the other side's tracked
      // changes? Ask ELI shows Respond beside Polish when it does.
      selection_has_theirs: function () {
        if (!_tdCan()) return Promise.resolve(false);
        return eli.host.runRaw("eli_agent:sel_theirs", function (context) {
          // Any change of theirs touching the highlighted text. Word lists a
          // range's changes only when wholly inside it, so highlighting part
          // of a deleted section found nothing.
          var sel = context.document.getSelection();
          var tcs = context.document.body.getTrackedChanges();
          tcs.load("items/author");
          return context.sync().then(function () {
            var names = [];
            (tcs.items || []).forEach(function (t) { if (t.author && names.indexOf(t.author) < 0) names.push(t.author); });
            var sides = _egSides(names);
            var where = (tcs.items || []).filter(function (t) { return t.author && sides[t.author].side === "counterparty"; })
              .map(function (t) { return t.getRange("Whole").compareLocationWith(sel); });
            if (!where.length) return false;
            return context.sync().then(function () { return where.some(function (w) { return !!TD_IN_SEL[w.value]; }); });
          });
        }).catch(function () { return false; });
      },
      open_agent: function (payload) {
        var p = payload || {};
        if (!_findAgent(p.agent)) return { ok: false, reason: "unknown agent: " + p.agent };
        _openAgentOverlay(p);
        return { ok: true };
      },
      get_current_mode: function () { return _currentMode; },
      set_mode: function (mode) { _setMode(mode); },
    },
    // Tile dispatch for users who pin the Manage Agents UI as a
    // standalone tile (audience controls keep this admin-only).
    tile: {
      app_eli_agent: function () {
        // 2026-05-17 v22: telemetry recording on tile launch.
        try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedEliAgent"); } catch (_) {}
        _openManageAgentsModal();
      },
